#!/usr/bin/env python3
"""Focused regression check for the NetworkManager `config_changed` fix.

This test is deliberately self-contained because the container lacks the glib/dbus/
systemd development headers required to build NetworkManager itself.  It does NOT
claim to build the project.  Instead it:

  1. locates the real `config_changed()` function in the target source tree,
  2. extracts the function text verbatim from that file,
  3. wraps it in a minimal C harness whose stub declarations mirror the real
     signatures/types used (NMDevicePrivate.state, NM_FLAGS_HAS,
     nm_device_get_applied_setting, device_init_static_sriov_num_vfs, ...),
  4. compiles the harness with the system gcc and runs it,
  5. asserts the upstream regression intent over every NMDeviceState value with
     and without an applied SR-IOV setting.

The C expressions under test are exactly the ones in the candidate/baseline file;
only the surrounding types/functions are stubbed.  The behaviour assertions are:

  patched : ACTIVATED (100) reloads config; static SR-IOV init is suppressed when
            an SR-IOV setting is applied.
  baseline: ACTIVATED (100) is skipped (the bug); static SR-IOV init is unguarded.
"""

from __future__ import annotations

import argparse
import re
import subprocess
import sys
import tempfile
from pathlib import Path

STATES = {
    "NM_DEVICE_STATE_UNKNOWN": 0,
    "NM_DEVICE_STATE_UNMANAGED": 10,
    "NM_DEVICE_STATE_UNAVAILABLE": 20,
    "NM_DEVICE_STATE_DISCONNECTED": 30,
    "NM_DEVICE_STATE_PREPARE": 40,
    "NM_DEVICE_STATE_CONFIG": 50,
    "NM_DEVICE_STATE_NEED_AUTH": 60,
    "NM_DEVICE_STATE_IP_CONFIG": 70,
    "NM_DEVICE_STATE_IP_CHECK": 80,
    "NM_DEVICE_STATE_SECONDARIES": 90,
    "NM_DEVICE_STATE_ACTIVATED": 100,
    "NM_DEVICE_STATE_DEACTIVATING": 110,
    "NM_DEVICE_STATE_FAILED": 120,
}

PREAMBLE = r"""
#include <stdio.h>
#include <string.h>

typedef struct { int state; int ignore_carrier; } NMDevicePrivate;
typedef struct { int unused; } NMConfig;
typedef struct { int unused; } NMConfigData;
typedef struct { int unused; } NMDevice;
typedef unsigned int NMConfigChangeFlags;

#define NM_DEVICE_GET_PRIVATE(self) (&g_priv)
#define NM_DEVICE_STATE_UNKNOWN 0
#define NM_DEVICE_STATE_UNMANAGED 10
#define NM_DEVICE_STATE_UNAVAILABLE 20
#define NM_DEVICE_STATE_DISCONNECTED 30
#define NM_DEVICE_STATE_PREPARE 40
#define NM_DEVICE_STATE_CONFIG 50
#define NM_DEVICE_STATE_NEED_AUTH 60
#define NM_DEVICE_STATE_IP_CONFIG 70
#define NM_DEVICE_STATE_IP_CHECK 80
#define NM_DEVICE_STATE_SECONDARIES 90
#define NM_DEVICE_STATE_ACTIVATED 100
#define NM_DEVICE_STATE_DEACTIVATING 110
#define NM_DEVICE_STATE_FAILED 120
#define NM_CONFIG_CHANGE_VALUES (1u << 0)
#define NM_FLAGS_HAS(flags, flag) (((flags) & (flag)) != 0)
#define NM_TYPE_SETTING_SRIOV 4242

static NMDevicePrivate g_priv;
static int g_carrier_value;
static int g_applied_sriov;
static int g_init_calls;

static int nm_config_data_get_ignore_carrier(NMConfigData *d, NMDevice *s) {
    (void) d; (void) s;
    return g_carrier_value;
}
static void *nm_device_get_applied_setting(NMDevice *s, int t) {
    (void) s; (void) t;
    return g_applied_sriov ? (void *) 1 : (void *) 0;
}
static void device_init_static_sriov_num_vfs(NMDevice *s) {
    (void) s;
    g_init_calls++;
}
"""

HARNESS_MAIN = r"""
static int failures = 0;

static int reloaded(int state, unsigned changes) {
    g_priv.state = state;
    g_priv.ignore_carrier = 0;
    g_carrier_value = 7;
    g_init_calls = 0;
    config_changed(NULL, NULL, changes, NULL, NULL);
    return g_priv.ignore_carrier == 7;
}

static int init_calls(int state, unsigned changes, int applied_sriov) {
    g_priv.state = state;
    g_carrier_value = 7;
    g_applied_sriov = applied_sriov;
    g_init_calls = 0;
    config_changed(NULL, NULL, changes, NULL, NULL);
    return g_init_calls;
}

int main(void) {
    int activated = %(activated)d;
    int prepare = NM_DEVICE_STATE_PREPARE;
    int changes_values = NM_CONFIG_CHANGE_VALUES;

    /* Every state at/below DISCONNECTED or at/above ACTIVATED must be reloaded. */
    int reload_states[] = { NM_DEVICE_STATE_UNKNOWN, NM_DEVICE_STATE_UNMANAGED,
                            NM_DEVICE_STATE_UNAVAILABLE, NM_DEVICE_STATE_DISCONNECTED,
                            NM_DEVICE_STATE_ACTIVATED, NM_DEVICE_STATE_DEACTIVATING,
                            NM_DEVICE_STATE_FAILED };
    int skip_states[] = { NM_DEVICE_STATE_PREPARE, NM_DEVICE_STATE_CONFIG,
                          NM_DEVICE_STATE_NEED_AUTH, NM_DEVICE_STATE_IP_CONFIG,
                          NM_DEVICE_STATE_IP_CHECK, NM_DEVICE_STATE_SECONDARIES };
    size_t i;

    for (i = 0; i < sizeof(reload_states)/sizeof(reload_states[0]); i++) {
        if (!reloaded(reload_states[i], changes_values)) {
            fprintf(stderr, "FAIL: state %%d should reload config\n", reload_states[i]);
            failures++;
        }
    }
    for (i = 0; i < sizeof(skip_states)/sizeof(skip_states[0]); i++) {
        if (reloaded(skip_states[i], changes_values)) {
            fprintf(stderr, "FAIL: state %%d should NOT reload config\n", skip_states[i]);
            failures++;
        }
    }

    /* No VALUES change flag -> no SRIOV init regardless. */
    if (init_calls(NM_DEVICE_STATE_ACTIVATED, 0, 0) != 0) {
        fprintf(stderr, "FAIL: no VALUES flag must not init static sriov\n");
        failures++;
    }

    if (activated) {
        /* Patched: applied SRIOV setting suppresses static init on active device. */
        if (init_calls(NM_DEVICE_STATE_ACTIVATED, changes_values, 1) != 0) {
            fprintf(stderr, "FAIL: applied SR-IOV setting must suppress static init\n");
            failures++;
        }
        if (init_calls(NM_DEVICE_STATE_ACTIVATED, changes_values, 0) != 1) {
            fprintf(stderr, "FAIL: no applied SR-IOV setting must init static sriov\n");
            failures++;
        }
    } else {
        /* Baseline: unguarded call runs even with an applied SR-IOV setting. */
        if (init_calls(NM_DEVICE_STATE_ACTIVATED, changes_values, 1) != 1) {
            fprintf(stderr, "FAIL: baseline expected unguarded static sriov init\n");
            failures++;
        }
    }

    if (failures) {
        fprintf(stderr, "%%d focused regression assertion(s) failed\n", failures);
        return 1;
    }
    printf("focused config_changed regression: all assertions passed (activated=%%d)\n", activated);
    return 0;
}
"""


def extract_function(source: Path) -> str:
    text = source.read_text(encoding="utf-8", errors="replace")
    match = re.search(r"^static void\nconfig_changed\(.*?\n\}\n", text, re.M | re.S)
    if not match:
        raise SystemExit(f"config_changed() not found in {source}")
    return match.group(0)


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--expect", choices=["patched", "baseline"], required=True)
    parser.add_argument("--source", default="src/core/devices/nm-device.c")
    args = parser.parse_args()

    source = Path(args.source)
    if not source.is_absolute():
        source = Path.cwd() / source
    function_text = extract_function(source)
    body = function_text
    if "static void\n" in body:
        body = body.replace("static void\n", "", 1)
    # Strip the 'static' so it compiles alongside the harness main; keep it as-is otherwise.
    harness = (
        PREAMBLE
        + "\nstatic void\n"
        + body
        + "\n"
        + HARNESS_MAIN % {"activated": 1 if args.expect == "patched" else 0}
    )

    with tempfile.TemporaryDirectory(prefix="nm-config-changed-") as tmp:
        c_path = Path(tmp) / "harness.c"
        bin_path = Path(tmp) / "harness"
        c_path.write_text(harness, encoding="utf-8")
        compile_result = subprocess.run(
            ["gcc", "-std=gnu11", "-Wall", "-Wextra", "-Werror", "-O0", str(c_path), "-o", str(bin_path)],
            capture_output=True,
            text=True,
        )
        if compile_result.returncode != 0:
            sys.stderr.write(compile_result.stdout)
            sys.stderr.write(compile_result.stderr)
            print("focused harness failed to compile")
            return 2
        run_result = subprocess.run([str(bin_path)], capture_output=True, text=True)
        sys.stdout.write(run_result.stdout)
        sys.stderr.write(run_result.stderr)
        return run_result.returncode


if __name__ == "__main__":
    raise SystemExit(main())

